2	#include "params/CHAOSPhysReg.hh"
3	
4	#include <iostream>
5	#include <fstream>
6	#include <vector>
7	#include <random>
8	#include <bitset>
9	
10	#include "base/output.hh"
11	#include "cpu/o3/cpu.hh"
12	#include "cpu/o3/regfile.hh"
13	#include "cpu/o3/rename_map.hh"
14	#include "arch/generic/isa.hh"
15	
16	namespace gem5
17	{
18	
19	    CHAOSPhysReg::CHAOSPhysReg(const CHAOSPhysRegParams &p)
20	        : SimObject(p),
21	          cpu(dynamic_cast<o3::CPU *>(p.cpu)),
22	          fi_mode(stringToMode(p.injectionMode)),
23	          target_phys_idx(p.targetPhysRegIdx),
24	          target_arch_idx(p.targetArchRegIdx),
25	          probability(p.probability),
26	          num_bits_to_change(p.bitsToChange),
27	          fault_type_enum(stringToFaultType(p.faultType)),
28	          fault_mask(std::bitset<32>(p.faultMask)),
29	          bit_flip_prob(0.9),
30	          stuck_at_zero_prob(0.05),
31	          stuck_at_one_prob(0.05),
32	          first_clock(Cycles(p.firstClock)),
33	          last_clock(Cycles(p.lastClock)),
34	          max_faults(p.maxFaults),
35	          faults_injected_count(0),
36	          rng_seed(p.rngSeed),
37	          write_log(p.writeLog),
38	          attackEvent([this] { this->attackCheck(); }, name()),
39	          periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
40	          readTraceEvent([this] { this->readTraceCheck(); }, name() + ".readTrace"),
41	          stats(nullptr)
42	    {
43	        if (!cpu) {
44	            throw std::runtime_error(
45	                "CHAOSPhysReg: cpu is not an O3CPU. CHAOSPhysReg only supports "
46	                "O3CPU (it needs regFile/renameMap). Cast failed.");
47	        }
48	        if (probability > 0.0) {
49	            log_stream = simout.create("fault_injections.log", false, true);
50	            if (!log_stream || !log_stream->stream()) {
51	                panic("CHAOSPhysReg: Could not open log file");
52	            }
53	            stats = std::make_unique<CHAOSPhysRegStats>(this);
54	            rng.seed(rng_seed != 0 ? rng_seed : rd());
55	            if (num_bits_to_change == -1) {
56	                std::uniform_int_distribution<int> dist(1, 32);
57	                num_bits_to_change = dist(rng);
58	            }
59	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
60	            unsigned next_fault_cycle_distance = inter_fault_cycles_dist(rng);
61	            scheduleAttackEvent(first_clock + Cycles(next_fault_cycle_distance));
62	            scheduleCheckPermanentFault(first_clock + Cycles(1));
63	        }
64	    }
65	
