141	    // Core: resolve a target PHYSICAL register id according to the fi_mode,
142	    // then read-modify-write it directly in the physical register file.
143	    // This is the key difference from CHAOSReg (which wrote the commitRenameMap
144	    // phys reg via ThreadContext::setReg — a backdoor that doesn't propagate
145	    // to in-flight instructions on O3).
146	    void
147	    CHAOSPhysReg::processFault(ThreadID tid)
148	    {
149	        // 1. Resolve target physical register id.
150	        PhysRegIdPtr phys_reg = nullptr;
151	        int chosen_phys_idx = -1;     // for logging
152	        int chosen_arch_idx = -1;     // for logging (arch modes)
153	
154	        if (fi_mode == Mode::Phys) {
155	            // Inject by physical register index. A real defective cell has no
156	            // notion of architectural registers; whoever is allocated to this
157	            // slot gets hit. This is the ITC'23/GeFIN abstraction.
158	            int n = cpu->physRegFile().numIntPhysRegs();
159	            if (n <= 0) return;
160	            chosen_phys_idx = (target_phys_idx >= 0)
161	                ? target_phys_idx
162	                : std::uniform_int_distribution<>(0, n - 1)(rng);
163	            if (chosen_phys_idx >= n) return;
164	            phys_reg = cpu->physRegFile().intPhysRegId(chosen_phys_idx);
165	
166	            // Liveness probe: is this physical slot currently FREE (inactive)
167	            // or ALLOCATED (active)? Correct criterion per project notes: a phys
168	            // reg NOT in the free list is allocated — it may be held as a source
169	            // by in-flight renamed-but-unexecuted instructions even if no rename
170	            // map entry currently maps it (older version superseded but not yet
171	            // released). So "not free" = active = may be read. (The earlier
172	            // "rename map reverse-walk" criterion was too narrow and mislabeled
173	            // some live slots as dead, producing the dead-slot SDC anomaly.)
174	            bool is_free = cpu->physFreeList().isFree(
175	                gem5::IntRegClass, phys_reg);
176	            free_list_size_at_inject = cpu->physFreeList().numFreeRegs(
177	                gem5::IntRegClass);
178	            if (!is_free) {
179	                // active — also record which arch reg (if any) maps to it now,
180	                // for diagnostics (walk rename map; best-effort, not the
181	                // liveness source of truth).
182	                gem5::ThreadContext *tc = cpu->getContext(tid);
183	                if (tc) {
184	                    gem5::BaseISA *isa = tc->getIsaPtr();
185	                    if (isa) {
186	                        const auto &rc = isa->regClasses();
187	                        const gem5::RegClass *ic = rc[gem5::IntRegClass];
188	                        int na = ic ? ic->numRegs() : 0;
189	                        int cap = na < 31 ? na : 31;  // X0-X30
190	                        for (int a = 0; a < cap; a++) {
191	                            gem5::RegId ar(*ic, a);
192	                            const gem5::RegId flat = ar.flatten(*isa);
193	                            PhysRegIdPtr pm = cpu->frontRenameMap()[tid].lookup(flat);
194	                            if (pm && pm->index() == chosen_phys_idx) {
195	                                chosen_arch_idx = a;
196	                                break;
197	                            }
198	                        }
199	                    }
200	                }
201	            } else {
202	                chosen_arch_idx = -2;  // sentinel: free/inactive
203	            }
204	        } else {
205	            // arch_frontend: renameMap.lookup      (in-flight mapping)
206	            // arch_commit:   commitRenameMap.lookup (committed mapping = CHAOSReg)
207	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
208	            if (!thread_context) return;
209	            gem5::BaseISA *isa = thread_context->getIsaPtr();
210	            if (!isa) return;
211	            const auto &reg_classes = isa->regClasses();
212	            const gem5::RegClass *reg_class = reg_classes[gem5::IntRegClass];
213	            if (!reg_class || reg_class->numRegs() == 0) return;
214	            int arch_idx = target_arch_idx;
215	            if (arch_idx < 0 || arch_idx >= reg_class->numRegs()) return;
216	            chosen_arch_idx = arch_idx;
217	            gem5::RegId arch_reg(*reg_class, arch_idx);
218	            // flatten to match the per-class rename map's indexing
219	            const gem5::RegId flat = arch_reg.flatten(*isa);
220	            if (fi_mode == Mode::ArchFrontend)
221	                phys_reg = cpu->frontRenameMap()[tid].lookup(flat);
222	            else // ArchCommit
223	                phys_reg = cpu->commitRenameMapAccess()[tid].lookup(flat);
224	            if (!phys_reg) return;
225	            chosen_phys_idx = phys_reg->index();
226	        }
227	
228	        if (!phys_reg) return;
229	
230	        // 2. Read current physical reg value, apply fault, write back.
231	        gem5::RegVal reg_val = cpu->physRegFile().getReg(phys_reg);
232	
233	        int mask = fault_mask.any()
234	            ? fault_mask.to_ulong()
235	            : generateRandomMask(rng, num_bits_to_change, sizeof(reg_val) << 3);
236	
237	        FaultType chosen = fault_type_enum;
238	        if (fault_type_enum == FaultType::Random) {
239	            int idx = random_fault_distribution(rng);
240	            chosen = static_cast<FaultType>(idx);
241	        }
242	
243	        switch (chosen) {
244	            case FaultType::StuckAtZero:
245	                reg_val &= ~mask;
246	                stats->numStuckAtZero++;
247	                stats->numPermanentFaults++;
248	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
249	                break;
250	            case FaultType::StuckAtOne:
251	                reg_val |= mask;
252	                stats->numStuckAtOne++;
253	                stats->numPermanentFaults++;
254	                permanent_faults[{tid, chosen_phys_idx}] = {chosen, mask, true};
255	                break;
256	            case FaultType::BitFlip:
257	                reg_val ^= mask;
258	                stats->numBitFlips++;
259	                break;
260	            default: break;
261	        }
262	
263	        cpu->physRegFile().setReg(phys_reg, reg_val);
264	        stats->numFaultsInjected++;
265	        ++faults_injected_count;
266	
267	        // Start read-tracing this phys slot until workload end, to measure
268	        // whether the injected cell is actually read after injection.
269	        // (Closure check: SDC|read>0 should be similar for layer2 & layer3,
270	        //  SDC|read==0 should be ~0.) The readTraceEvent reschedules itself
271	        // every 1000 cycles until all threads halt, then writes the final
272	        // read count to the log.
273	        traced_phys_idx = chosen_phys_idx;
274	        reads_before_overwrite = 0;
275	        trace_overwritten = false;
276	        overwrite_recorded = false;
277	        overwritten_at_cycle = 0;
278	        cpu->physRegFile().setReadTraceTarget(chosen_phys_idx);
279	        if (!readTraceEvent.scheduled()) {
280	            schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
281	        }
282	
283	        if (write_log) {
284	            *(log_stream->stream())
285	                << "Cycle: " << cpu->curCycle()
286	                << ", CPU: " << cpu->name()
287	                << ", Thread: " << tid
288	                << ", Mode: " << (fi_mode == Mode::Phys ? "phys"
289	                              : fi_mode == Mode::ArchFrontend ? "arch_frontend"
290	                              : "arch_commit")
291	                << ", PhysReg[" << chosen_phys_idx << "]"
292	                << (fi_mode == Mode::Phys
293	                    ? (chosen_arch_idx == -2
294	                       ? " (Inactive/free slot)"
295	                       : (chosen_arch_idx >= 0
296	                          ? " (Active, mapped from ArchReg[" + std::to_string(chosen_arch_idx) + "])"
297	                          : " (Active, held by in-flight inst, no current rename-map entry)"))
298	                    : (chosen_arch_idx >= 0
299	                       ? " (<= ArchReg[" + std::to_string(chosen_arch_idx) + "])"
300	                       : ""))
301	                << ", FaultType: " << faultTypeToString(chosen)
302	                << ", Mask: " << std::bitset<32>(mask)
303	                << ", FreeListSize: " << free_list_size_at_inject
304	                << std::endl;
305	        }
306	    }
307	
308	    void
309	    CHAOSPhysReg::attackCheck()
310	    {
311	        if (!probability) return;
312	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
313	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
314	            if (!thread_context || thread_context->status() == ThreadContext::Halted)
315	                continue;
316	            processFault(tid);
317	        }
318	        // maxFaults cap (mirrors CHAOSReg)
319	        if (max_faults != 0 && faults_injected_count >= max_faults) {
320	            unscheduleAttackEvent();
321	            return;
322	        }
323	        bool any_active = false;
324	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
325	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
326	            if (thread_context && thread_context->status() != ThreadContext::Halted) {
327	                any_active = true; break;
328	            }
329	        }
330	        if (any_active) {
331	            Cycles next = Cycles(inter_fault_cycles_dist(rng));
332	            if (last_clock == 0 || (next + cpu->curCycle()) <= last_clock)
333	                scheduleAttackEvent(next);
334	        } else {
335	            unscheduleAttackEvent();
336	        }
337	    }
338	
339	    void
340	    CHAOSPhysReg::checkPermanent()
341	    {
342	        // NOTE: periodic re-apply is the WRONG stuck mechanism (see project
343	        // notes). The correct one is a write-path mask hook in
344	        // PhysRegFile::setReg. This periodic re-apply is kept only as a
345	        // fallback for the 'arch_*' modes' compatibility and will NOT make
346	        // stuck faults truly permanent on O3 for the same reason CHAOSReg's
347	        // didn't propagate (commits vs in-flight). Phys-fi_mode stuck also needs
348	        // the write-path mask to be correct.
349	        for (auto &entry : permanent_faults) {
350	            if (!entry.second.update) continue;
351	            ThreadID tid = entry.first.first;
352	            int phys_idx = entry.first.second;
353	            if (phys_idx < 0 || phys_idx >= cpu->physRegFile().numIntPhysRegs()) continue;
354	            PhysRegIdPtr phys_reg = cpu->physRegFile().intPhysRegId(phys_idx);
355	            try {
356	                gem5::RegVal v = cpu->physRegFile().getReg(phys_reg);
357	                switch (entry.second.fault_type) {
358	                    case FaultType::StuckAtZero: v &= ~entry.second.mask; break;
359	                    case FaultType::StuckAtOne:  v |= entry.second.mask; break;
360	                    default: break;
361	                }
362	                cpu->physRegFile().setReg(phys_reg, v);
363	                entry.second.update = false; // (kept for compatibility; TODO remove + write-path mask)
364	            } catch (...) {}
365	            scheduleCheckPermanentFault(Cycles(1));
366	        }
367	    }
368	
369	    void
370	    CHAOSPhysReg::readTraceCheck()
371	    {
372	        // Poll the PhysRegFile's read counter for the INJECTED VALUE.
373	        // Counting stops once the slot is written (injected value destroyed),
374	        // so reads_before_overwrite = # reads of the injected value specifically.
375	        reads_before_overwrite = cpu->physRegFile().getReadsBeforeOverwrite();
376	        // Capture the cycle at the moment the value is overwritten (once).
377	        if (cpu->physRegFile().isTraceOverwritten() && !overwrite_recorded) {
378	            overwritten_at_cycle = cpu->curCycle();
379	            overwrite_recorded = true;
380	        }
381	        if (write_log) {
382	            *(log_stream->stream())
383	                << "ReadTracePoll: cycle " << cpu->curCycle()
384	                << " PhysReg[" << traced_phys_idx
385	                << "] reads_before_overwrite=" << reads_before_overwrite
386	                << " overwritten=" << (overwrite_recorded ? 1 : 0)
387	                << (overwrite_recorded ? (" at_cycle=" + std::to_string(overwritten_at_cycle)) : "")
388	                << std::endl;
389	        }
390	        bool any_active = false;
391	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
392	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
393	            if (thread_context && thread_context->status() != ThreadContext::Halted) {
394	                any_active = true; break;
395	            }
396	        }
397	        if (any_active) {
398	            schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
399	        } else {
400	            if (write_log) {
401	                *(log_stream->stream())
402	                    << "ReadTraceFinal: PhysReg[" << traced_phys_idx
403	                    << "] reads_before_overwrite=" << reads_before_overwrite
404	                    << " overwritten=" << (overwrite_recorded ? 1 : 0)
405	                    << (overwrite_recorded ? (" at_cycle=" + std::to_string(overwritten_at_cycle)) : "")
406	                    << " (workload halted)"
407	                    << std::endl;
408	            }
409	            cpu->physRegFile().clearReadTraceTarget();
410	            traced_phys_idx = -1;
411	        }
412	    }
