16	    CHAOSReg::CHAOSReg(const CHAOSRegParams &p)
17	        : SimObject(p),
18	        cpu(dynamic_cast<BaseCPU *>(p.cpu)),
19	        probability(p.probability),
20	        num_bits_to_change(p.bitsToChange),
21	        first_clock(Cycles(p.firstClock)),
22	        last_clock(Cycles(p.lastClock)),
23	        max_faults(p.maxFaults),
24	        faults_injected_count(0),
