28	        fault_mask(std::bitset<32>(p.faultMask)),
29	        bit_flip_prob(p.bitFlipProb),
30	        stuck_at_zero_prob(p.stuckAtZeroProb),
31	        stuck_at_one_prob(p.stuckAtOneProb),
