35	        write_log(p.writeLog),
36	        attackEvent([this] { this->attackCheck(); }, name()),
37	        periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
38	        stats(nullptr)
39	    {
40	        if (probability > 0.0){
41	            if (!cpu) {
42	                throw std::runtime_error("CHAOSReg: Invalid CPU pointer.\n");
43	            }
44	
45	            log_stream = simout.create("fault_injections.log", false, true);
46	            if (!log_stream || !log_stream->stream()) {
47	                panic("CHAOSReg: Could not open log file");
48	            }
49	
50	            stats = std::make_unique<CHAOSRegStats>(this);
51	
52	            // Reproducibility: if rng_seed is set (nonzero), use it; otherwise
53	            // fall back to std::random_device (original, non-reproducible).
54	            rng.seed(rng_seed != 0 ? rng_seed : rd());
55	            if (PC_target != 0){
56	                // In this case, it is necessary to check at every cycle if the PC matches, so it is better to set the probability to 1.
57	                probability = 1;
58	            }
59	
60	            if (num_bits_to_change == -1){
61	                std::uniform_int_distribution<int> dist(1, 32);
62	                num_bits_to_change = dist(rng);
63	            }
64	
65	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
66	            
67	            unsigned next_fault_cycle_distance = inter_fault_cycles_dist(rng);
68	            scheduleAttackEvent(first_clock + Cycles(next_fault_cycle_distance));
69	            
70	            if ((bit_flip_prob + stuck_at_zero_prob + stuck_at_one_prob) != 1.0){
71	                warn("Sum of probabilities is not 1, assuming 0.9 for bitFlipProb, 0.05 for stuckAtZeroProb and 0.05 for stuckAtOneProb.\n");
72	                bit_flip_prob = 0.9;
73	                stuck_at_zero_prob = 0.05;
74	                stuck_at_one_prob = 0.05;
75	            }
76	
77	            std::vector<double> weights = {bit_flip_prob, stuck_at_zero_prob, stuck_at_one_prob};
78	            random_fault_distribution = std::discrete_distribution<int>(weights.begin(), weights.end());
79	
80	            scheduleCheckPermanentFault(first_clock + cycles_permament_fault_check);
81	        }
82	    }
