150	    int 
151	    CHAOSReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
152	    {
153	        int mask = 0;
154	        std::uniform_int_distribution<int> bitDist(0, len-1);
155	
156	        while (bits_to_change-- > 0) {
157	            mask |= (1 << bitDist(gen));
158	        }
159	        return mask;
160	    }
