162	    void 
163	    CHAOSReg::processFault(ThreadID tid)
164	    {
165	        gem5::ThreadContext *thread_context = cpu->getContext(tid);
166	        if (!thread_context)
167	            return;
168	    
169	        gem5::BaseISA *isa = thread_context->getIsaPtr();
170	        if (!isa)
171	            return;
172	    
173	        const auto &reg_classes = isa->regClasses();
174	        const gem5::RegClass *reg_class = nullptr;
175	    
176	        if (reg_target_class_enum == TargetClass::Both) {
177	            int intRegs = reg_classes[gem5::IntRegClass]->numRegs();
178	            int floatRegs = reg_classes[gem5::FloatRegClass]->numRegs();
179	
180	            if (intRegs == 0 && floatRegs == 0) {
181	                warn("processFault: No registers found\n");
182	                return;
183	            } 
184	            if (intRegs > 0 && floatRegs == 0) {
185	                reg_class = reg_classes[gem5::IntRegClass];
186	            } else if (intRegs == 0 && floatRegs > 0) {
187	                reg_class = reg_classes[gem5::FloatRegClass];
188	            } else {
189	                reg_class = (rand() % 2 == 0) ? reg_classes[gem5::IntRegClass] : reg_classes[gem5::FloatRegClass];
190	            }
191	        } else if (reg_target_class_enum == TargetClass::Integer) {
192	            reg_class = reg_classes[gem5::IntRegClass];
193	            if (reg_class->numRegs() == 0) return;
194	        } else if (reg_target_class_enum == TargetClass::FloatingPoint) {
195	            reg_class = reg_classes[gem5::FloatRegClass];
196	            if (reg_class->numRegs() == 0) return;
197	        }
198	    
199	        if (!reg_class || reg_class->numRegs() == 0)
200	            return;
201	
202	        // Register index upper bound. The original code sampled over the full
203	        // numRegs() of the class, which on aarch64 IntRegClass includes:
204	        //   integer[31] = Zero (the zero register — injecting it has NO effect),
205	        //   integer[32+] = AArch32 banked-mode copies + non-architectural slots
206	        //   (not live in aarch64 user mode — injecting them has NO effect).
207	        // Both systematically inflate the Masked rate and underestimate SDC.
208	        // max_reg_idx (exclusive upper bound) lets the caller restrict to the
209	        // live architectural range; 0 = original full-range behavior.
210	        int num_regs = reg_class->numRegs();
211	        int upper = num_regs - 1;
212	        if (max_reg_idx > 0 && max_reg_idx < num_regs)
213	            upper = max_reg_idx - 1;
214	
215	        int random_reg = std::uniform_int_distribution<>(0, upper)(rng);
216	        gem5::RegId reg_id(*reg_class, random_reg);
217	        
218	        try {
219	            gem5::RegVal reg_val = thread_context->getReg(reg_id);
220	
221	            int mask = fault_mask.any() ? fault_mask.to_ulong() : generateRandomMask(rng, num_bits_to_change, sizeof(reg_val) << 3);
222	    
223	            FaultType chosen_fault_type_enum = fault_type_enum;
224	            if (fault_type_enum == FaultType::Random) {
225	                int faultIdx = random_fault_distribution(rng);
226	                chosen_fault_type_enum = static_cast<FaultType>(faultIdx);
227	            }
228	    
229	            switch (chosen_fault_type_enum) {
230	                case FaultType::StuckAtZero:
231	                    reg_val &= ~mask;
232	                    stats->numStuckAtZero++;
233	                    stats->numPermanentFaults++;
234	                    permanent_faults[std::make_pair(tid, reg_id)] = {chosen_fault_type_enum, mask, true};
235	                    break;
236	                case FaultType::StuckAtOne:
237	                    reg_val |= mask;
238	                    stats->numStuckAtOne++;
239	                    stats->numPermanentFaults++;
240	                    permanent_faults[std::make_pair(tid, reg_id)] = {chosen_fault_type_enum, mask, true};
241	                    break;
242	                case FaultType::BitFlip:
243	                    reg_val ^= mask;
244	                    stats->numBitFlips++;
245	                    break;
246	                default:
247	                    break;
248	            }
249	    
250	            thread_context->setReg(reg_id, reg_val);
251	            stats->numFaultsInjected++;
252	            ++faults_injected_count;
253	            
254	            if (write_log){
255	                *(log_stream->stream())  << "Cycle: " << cpu->curCycle()
256	                    << ", CPU: " << cpu->name()
257	                    << ", Thread: " << tid
258	                    << ", Register: " << reg_class->name() << "[" << random_reg << "]"
259	                    << ", FaultType: " << faultTypeToString(chosen_fault_type_enum)
260	                    << ", Mask: " << std::bitset<32>(mask)
261	                    << std::endl;
262	            }
263	
264	        } catch (const std::exception &e) {
265	            *(log_stream->stream())  << "Error: Exception during fault injection. "
266	                    << "ThreadID: " << tid
267	                    << ", Error: " << e.what() << std::endl;
268	        } catch (...) {
269	            *(log_stream->stream())  << "Error: Unknown exception during fault injection. "
270	                    << "ThreadID: " << tid << std::endl;
271	        }
272	    }
273	
274	    void 
275	    CHAOSReg::attackCheck()
276	    {
277	        if (!probability)
278	            return;
279	
280	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
281	            ThreadContext *thread_context = cpu->getContext(tid);
282	            if (!thread_context || thread_context->status() == ThreadContext::Halted) {
283	                continue;
284	            }
285	
286	            if (PC_target == 0 || (PC_target == thread_context->pcState().instAddr())) {
287	                processFault(tid);
288	            }
289	        }
290	
291	        bool any_active = false;
292	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
293	            ThreadContext *thread_context = cpu->getContext(tid);
294	            if (thread_context && thread_context->status() != ThreadContext::Halted) {
295	                any_active = true;
296	                break;
297	            }
298	        }
299	        if (any_active) {
300	            // maxFaults cap: if we've already injected the requested number of
301	            // faults, stop rescheduling. max_faults == 0 means unlimited
302	            // (original CHAOS behavior). This is what makes "inject exactly
303	            // N faults" achievable; without it the original code keeps
304	            // rescheduling every (geometric) interval for the whole run.
305	            if (max_faults != 0 && faults_injected_count >= max_faults) {
306	                unscheduleAttackEvent();
307	                return;
308	            }
309	
310	            Cycles next_injection = Cycles(inter_fault_cycles_dist(rng));
311	            // last_clock semantics (NOTE: diverges from README.md):
312	            //   - The default is 0 (see CHAOSReg.py), NOT -1 as README claims.
313	            //   - last_clock == 0 here means "no upper bound / unrestricted".
314	            //     This is the real "off switch" for the window, NOT -1.
315	            //   - If set to a nonzero value, injection stops rescheduling once
316	            //     curCycle() passes it. CAUTION: if the first geometric-sampled
317	            //     injection lands past this value, numFaultsInjected stays 0
318	            //     with NO error (silent zero-injection). Prefer maxFaults for
319	            //     count control and leave last_clock == 0.
320	            //   - A literal -1, via uint64_t wraparound (Cycles holds
321	            //     uint64_t), becomes 0xFFFF...F which also passes this gate,
322	            //     so README's "-1 means unrestricted" only works by accident.
323	            if (last_clock == 0 || (next_injection + cpu->curCycle()) <= last_clock){
324	                scheduleAttackEvent(next_injection);
325	            }
326	        } else {
327	            unscheduleAttackEvent();
328	        }
329	    }
330	
331	    void 
332	    CHAOSReg::checkPermanent()
333	    {
334	        for (auto &entry : permanent_faults) {
335	            if (!entry.second.update)
336	                continue;
337	
338	            ThreadID tid = entry.first.first;
339	            gem5::RegId reg_id = entry.first.second;
340	            const PermanentFault &fault = entry.second;
341	
342	            try {
343	                gem5::ThreadContext *thread_context = cpu->getContext(tid);
344	                if (!thread_context)
345	                    continue;
346	
347	                gem5::RegVal reg_val = thread_context->getReg(reg_id);
348	
349	                switch (fault.fault_type) {
350	                    case FaultType::StuckAtZero:
351	                        reg_val &= ~fault.mask;
352	                        break;
353	                    case FaultType::StuckAtOne:
354	                        reg_val |= fault.mask;
355	                        break;
356	                    default:
357	                        break;
358	                }
359	
360	                thread_context->setReg(reg_id, reg_val);
361	                // NOTE: the original code cleared `update = false` here, which
362	                // meant the stuck mask was re-applied only ONCE after injection.
363	                // Any subsequent program write to this register would overwrite
364	                // the stuck value and the fault would silently disappear — so
365	                // "stuck_at_zero/one" were NOT actually permanent, under-applying
366	                // the fault model. Leaving `update = true` so checkPermanent
367	                // re-applies the mask every cyclesPermamentFaultCheck cycles,
368	                // making the stuck fault truly permanent (the correct model
369	                // for real permanent defects, e.g. stuck-at faults in silicon).
370	            } catch (const std::exception &e) {
371	                *(log_stream->stream())  << "Error: Exception during fault injection. "
372	                        << "ThreadID: " << tid
373	                        << ", Error: " << e.what() << std::endl;
374	            } catch (...) {
375	                *(log_stream->stream())  << "Error: Unknown exception during fault injection. "
376	                        << "ThreadID: " << tid << std::endl;
377	            }
378	
379	            scheduleCheckPermanentFault(cycles_permament_fault_check);
380	        }
381	    }
